//! The market's account lookup (#151): the token, the answer's verification
//! (pure), the fetch, cache, breaker and recheck against a local market (an
//! axum server on 127.0.0.1, no network), and the mint derivation against
//! DynamoDB Local (those return early unless `AUTHNZ_TEST_DYNAMODB_ENDPOINT`
//! is set, as CI's `test` job sets it).
//!
//! Every key and token here is generated by the test that uses it.

use super::*;
use crate::AppState;
use crate::constants::{ENTITLEMENT_CREATOR_PUBLISH, ENTITLEMENT_ONLINE_PLAY};
use crate::market::{SessionId, verify_claim};
use axum::extract::{Path, State};
use axum::http::{HeaderMap, StatusCode};
use axum::response::{IntoResponse, Response};
use axum::routing::get;
use axum::{Json, Router};
use base64::Engine;
use base64::engine::general_purpose::URL_SAFE_NO_PAD;
use p256::ecdsa::signature::Signer;
use p256::ecdsa::{Signature, SigningKey};
use serde_json::json;
use std::sync::Arc;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::time::Duration;

const AUDIENCE: &str = "https://identity.example";

fn key() -> SigningKey {
    SigningKey::random(&mut p256::elliptic_curve::rand_core::OsRng)
}

/// A fresh token of the shape the market requires.
fn token_text() -> String {
    format!("{}{}", Uuid::new_v4().simple(), Uuid::new_v4().simple())
}

fn kid_of(key: &SigningKey) -> String {
    let point = key.verifying_key().to_encoded_point(false);
    crate::market::thumbprint(point.x().unwrap(), point.y().unwrap())
}

fn sign(key: &SigningKey, payload: &Value) -> String {
    let header = json!({"alg": "ES256", "kid": kid_of(key), "typ": "JWT"});
    let input = format!(
        "{}.{}",
        URL_SAFE_NO_PAD.encode(header.to_string()),
        URL_SAFE_NO_PAD.encode(payload.to_string())
    );
    let sig: Signature = key.sign(input.as_bytes());
    format!("{input}.{}", URL_SAFE_NO_PAD.encode(sig.to_bytes()))
}

/// The payload the market signs for `account`, with `overrides` merged in
/// (a `null` removes a member).
fn payload(cfg: &MarketConfig, account: &Uuid, overrides: Value) -> Value {
    let mut p = json!({
        "iss": cfg.issuer,
        "aud": cfg.audience,
        "sub": account.hyphenated().to_string(),
        "tier": "online-play",
        "offer": "arkavo-online-play",
        "livemode": true,
        "iat": 1_793_923_200,
    });
    for (k, v) in overrides.as_object().unwrap() {
        if v.is_null() {
            p.as_object_mut().unwrap().remove(k);
        } else {
            p[k] = v.clone();
        }
    }
    p
}

// --------- The token ---------

#[test]
fn the_token_must_be_long_printable_and_unspaced_and_is_never_printed() {
    assert!(LookupToken::parse(None).unwrap().is_none());
    assert!(LookupToken::parse(Some("  ")).unwrap().is_none());

    let good = token_text();
    let token = LookupToken::parse(Some(&format!(" {good}\n")))
        .unwrap()
        .unwrap();
    assert!(token.0.is_sensitive());
    assert_eq!(token.0.to_str().unwrap(), format!("Bearer {good}"));
    assert!(!format!("{token:?}").contains(&good));
    let lookup = SubscriptionLookup::new(token);
    assert!(!format!("{lookup:?}").contains(&good));

    let short = &good[..31];
    let spaced = format!("{} {}", &good[..20], &good[20..]);
    let non_ascii = format!("{good}é");
    let control = format!("{good}\u{7}");
    for bad in [short, &spaced, &non_ascii, &control] {
        let err = LookupToken::parse(Some(bad)).unwrap_err();
        assert!(!err.contains(bad), "the error must not carry the value");
    }
}

// --------- The answer's claim ---------

#[test]
fn an_answer_verifies_only_for_the_account_asked_about() {
    let key = key();
    let cfg = MarketConfig::for_tests("https://market.example", AUDIENCE, &key);
    let account = Uuid::new_v4();
    let claim = |overrides: Value| sign(&key, &payload(&cfg, &account, overrides));

    assert_eq!(verify_answer(&cfg, &claim(json!({})), &account), Ok(()));

    let other = Uuid::new_v4();
    let cases = [
        (
            json!({ "sub": other.to_string() }),
            ClaimError::WrongAccount,
        ),
        // Never the OIDC `sub`, another spelling, or absent.
        (
            json!({ "sub": format!("arkavo:{account}") }),
            ClaimError::WrongAccount,
        ),
        (
            json!({ "sub": account.to_string().to_uppercase() }),
            ClaimError::WrongAccount,
        ),
        (json!({ "sub": null }), ClaimError::WrongAccount),
        (json!({ "tier": "lifetime" }), ClaimError::UnknownTier),
        (
            json!({ "tier": "online-play-plus" }),
            ClaimError::UnknownTier,
        ),
        (json!({ "tier": null }), ClaimError::UnknownTier),
        (json!({ "livemode": null }), ClaimError::Malformed),
        (json!({ "livemode": "true" }), ClaimError::Malformed),
        (json!({ "livemode": false }), ClaimError::TestMode),
        (
            json!({ "iss": "https://elsewhere.example" }),
            ClaimError::WrongIssuer,
        ),
        (
            json!({ "aud": "https://elsewhere.example" }),
            ClaimError::WrongAudience,
        ),
    ];
    for (overrides, error) in cases {
        assert_eq!(
            verify_answer(&cfg, &claim(overrides.clone()), &account),
            Err(error),
            "{overrides}"
        );
    }
    // The same claim asked about another account.
    assert_eq!(
        verify_answer(&cfg, &claim(json!({})), &other),
        Err(ClaimError::WrongAccount)
    );
    // Signed by a key that is not pinned.
    let stranger = self::key();
    assert_eq!(
        verify_answer(
            &cfg,
            &sign(&stranger, &payload(&cfg, &account, json!({}))),
            &account
        ),
        Err(ClaimError::UnknownKey)
    );
    assert_eq!(
        verify_answer(&cfg, "not.a.jws", &account),
        Err(ClaimError::Malformed)
    );
}

#[test]
fn a_test_mode_answer_verifies_only_while_test_mode_is_on() {
    let key = key();
    let mut cfg = MarketConfig::for_tests("https://market.example", AUDIENCE, &key);
    let account = Uuid::new_v4();
    let claim = sign(&key, &payload(&cfg, &account, json!({ "livemode": false })));
    assert_eq!(
        verify_answer(&cfg, &claim, &account),
        Err(ClaimError::TestMode)
    );
    cfg.accept_test_mode = true;
    assert_eq!(verify_answer(&cfg, &claim, &account), Ok(()));
}

/// The two claims share keys, issuer and audience. Neither may pass for the
/// other: a membership never answers a lookup, and a lookup answer never
/// links as a purchase.
#[test]
fn membership_claims_and_lookup_answers_are_not_interchangeable() {
    let key = key();
    let cfg = MarketConfig::for_tests("https://market.example", AUDIENCE, &key);
    let account = Uuid::new_v4();
    let id = SessionId::parse(&format!("cs_live_{}", Uuid::new_v4().simple())).unwrap();

    let membership = sign(
        &key,
        &json!({
            "iss": cfg.issuer,
            "aud": cfg.audience,
            "jti": format!("market#{}", id.as_str()),
            "tier": "lifetime",
            "livemode": true,
            "iat": 1_793_923_200,
        }),
    );
    assert!(verify_claim(&cfg, &membership, &id).is_ok());
    assert_eq!(
        verify_answer(&cfg, &membership, &account),
        Err(ClaimError::WrongAccount)
    );
    // Even one that names the account is the wrong tier.
    let named = sign(
        &key,
        &payload(
            &cfg,
            &account,
            json!({ "tier": "lifetime", "jti": format!("market#{}", id.as_str()) }),
        ),
    );
    assert_eq!(
        verify_answer(&cfg, &named, &account),
        Err(ClaimError::UnknownTier)
    );

    let answer = sign(&key, &payload(&cfg, &account, json!({})));
    assert_eq!(verify_answer(&cfg, &answer, &account), Ok(()));
    assert_eq!(
        verify_claim(&cfg, &answer, &id),
        Err(ClaimError::WrongPurchase)
    );
    // With a `jti` added it still is not a membership tier.
    let with_jti = sign(
        &key,
        &payload(
            &cfg,
            &account,
            json!({ "jti": format!("market#{}", id.as_str()) }),
        ),
    );
    assert_eq!(
        verify_claim(&cfg, &with_jti, &id),
        Err(ClaimError::UnknownTier)
    );
}

// --------- A local market ---------

#[derive(Clone)]
enum Answer {
    /// 200 `{"status":"active","claim":…,"until":…}`.
    Active(String),
    /// 200 with this body.
    Body(String),
    /// This status.
    Status(u16),
    Redirect,
    /// Never answers within the deadline.
    Slow,
}

#[derive(Clone)]
struct Market {
    /// What the market expects in `Authorization`.
    bearer: String,
    answers: Arc<Mutex<HashMap<String, Answer>>>,
    /// Requests that carried the right token.
    hits: Arc<AtomicUsize>,
    /// Requests refused for a missing or wrong token.
    refused: Arc<AtomicUsize>,
    /// The path and query of every request.
    seen: Arc<Mutex<Vec<String>>>,
}

async fn lookup_route(
    State(m): State<Market>,
    Path(id): Path<String>,
    uri: axum::http::Uri,
    headers: HeaderMap,
) -> Response {
    m.seen.lock().unwrap().push(uri.to_string());
    // The market checks the token before anything else.
    if headers.get("authorization").and_then(|v| v.to_str().ok()) != Some(m.bearer.as_str()) {
        m.refused.fetch_add(1, Ordering::SeqCst);
        return (
            StatusCode::UNAUTHORIZED,
            [("www-authenticate", "Bearer")],
            Json(json!({ "status": "unauthorized" })),
        )
            .into_response();
    }
    m.hits.fetch_add(1, Ordering::SeqCst);
    let answer = m.answers.lock().unwrap().get(&id).cloned();
    match answer {
        None => (StatusCode::NOT_FOUND, Json(json!({ "status": "none" }))).into_response(),
        Some(Answer::Active(claim)) => Json(json!({
            "status": "active",
            "claim": claim,
            "until": 1_800_000_000_i64,
        }))
        .into_response(),
        Some(Answer::Body(b)) => b.into_response(),
        Some(Answer::Status(s)) => StatusCode::from_u16(s).unwrap().into_response(),
        Some(Answer::Redirect) => {
            (StatusCode::FOUND, [("location", "/subscriptions/x")]).into_response()
        }
        Some(Answer::Slow) => {
            tokio::time::sleep(Duration::from_secs(MARKET_FETCH_DEADLINE_SECONDS + 5)).await;
            StatusCode::OK.into_response()
        }
    }
}

/// A local market and a source that looks subscriptions up there.
struct Harness {
    key: SigningKey,
    token: String,
    market: Market,
    source: MarketSource,
}

impl Harness {
    async fn new() -> Self {
        let token = token_text();
        Self::with_tokens(&token, &token).await
    }

    /// A market expecting `markets` and an identity sending `identitys`.
    async fn with_tokens(markets: &str, identitys: &str) -> Self {
        let market = Market {
            bearer: format!("Bearer {markets}"),
            answers: Arc::default(),
            hits: Arc::default(),
            refused: Arc::default(),
            seen: Arc::default(),
        };
        let app = Router::new()
            .route("/subscriptions/:id", get(lookup_route))
            .with_state(market.clone());
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let base = format!("http://{}", listener.local_addr().unwrap());
        tokio::spawn(async move { axum::serve(listener, app).await.unwrap() });
        let key = key();
        let source = MarketSource::new(MarketConfig::for_tests(&base, AUDIENCE, &key))
            .unwrap()
            .with_lookup_token(LookupToken::parse(Some(identitys)).unwrap().unwrap());
        Self {
            key,
            token: identitys.to_string(),
            market,
            source,
        }
    }

    fn lookup(&self) -> &SubscriptionLookup {
        self.source.subscriptions.as_ref().unwrap()
    }

    fn hits(&self) -> usize {
        self.market.hits.load(Ordering::SeqCst)
    }

    fn answer(&self, account: &Uuid, answer: Answer) {
        self.market
            .answers
            .lock()
            .unwrap()
            .insert(account.to_string(), answer);
    }

    fn claim(&self, account: &Uuid, overrides: Value) -> String {
        sign(&self.key, &payload(&self.source.config, account, overrides))
    }

    /// An account with a paid term.
    fn subscriber(&self) -> Uuid {
        let account = Uuid::new_v4();
        self.answer(&account, Answer::Active(self.claim(&account, json!({}))));
        account
    }

    fn with(&self, answer: Answer) -> Uuid {
        let account = Uuid::new_v4();
        self.answer(&account, answer);
        account
    }

    /// Close the breaker, as if its window had passed and a probe succeeded.
    fn close_breaker(&self) {
        *self.lookup().breaker_until.lock().unwrap() = 0;
    }

    fn breaker_open(&self) -> bool {
        *self.lookup().breaker_until.lock().unwrap() > Utc::now().timestamp()
    }
}

#[tokio::test]
async fn market_answers_map_to_subscriptions() {
    let h = Harness::new().await;
    let someone_else = Uuid::new_v4();
    let stranger = key();
    let unpinned = Uuid::new_v4();
    h.answer(
        &unpinned,
        Answer::Active(sign(
            &stranger,
            &payload(&h.source.config, &unpinned, json!({})),
        )),
    );
    let cases = [
        (h.subscriber(), Subscription::Active),
        (Uuid::new_v4(), Subscription::None),
        (h.with(Answer::Status(401)), Subscription::Unavailable),
        (h.with(Answer::Status(429)), Subscription::Unavailable),
        (h.with(Answer::Status(500)), Subscription::Unavailable),
        (h.with(Answer::Status(503)), Subscription::Unavailable),
        (h.with(Answer::Status(410)), Subscription::Unavailable),
        (h.with(Answer::Redirect), Subscription::Unavailable),
        // A 200 that does not verify is a failure, never "none".
        (unpinned, Subscription::Unavailable),
        (
            h.with(Answer::Active(h.claim(&someone_else, json!({})))),
            Subscription::Unavailable,
        ),
        (
            h.with(Answer::Body(r#"{"status":"active"}"#.into())),
            Subscription::Unavailable,
        ),
        (
            h.with(Answer::Body("not json".into())),
            Subscription::Unavailable,
        ),
        (
            h.with(Answer::Body("x".repeat(MARKET_CLAIM_MAX_BYTES + 1))),
            Subscription::Unavailable,
        ),
    ];
    for (account, expected) in cases {
        // Each case alone: a failure opens the breaker for the next.
        h.close_breaker();
        assert_eq!(
            h.source.subscription(&account, false).await,
            expected,
            "{account}"
        );
    }
    // A test-mode claim is a failure while test mode is off.
    h.close_breaker();
    let account = Uuid::new_v4();
    h.answer(
        &account,
        Answer::Active(h.claim(&account, json!({ "livemode": false }))),
    );
    assert_eq!(
        h.source.subscription(&account, false).await,
        Subscription::Unavailable
    );
}

#[tokio::test]
async fn the_token_travels_only_in_the_authorization_header() {
    let h = Harness::new().await;
    let account = h.subscriber();
    assert_eq!(
        h.source.subscription(&account, false).await,
        Subscription::Active
    );
    assert_eq!(h.market.refused.load(Ordering::SeqCst), 0);
    let seen = h.market.seen.lock().unwrap().clone();
    assert_eq!(seen, [format!("/subscriptions/{account}")]);
    assert!(seen.iter().all(|path| !path.contains(&h.token)));
}

#[tokio::test]
async fn a_wrong_token_is_an_outage_never_a_none() {
    let h = Harness::with_tokens(&token_text(), &token_text()).await;
    let account = h.subscriber();
    assert_eq!(
        h.source.subscription(&account, false).await,
        Subscription::Unavailable
    );
    assert_eq!(h.market.refused.load(Ordering::SeqCst), 1);
    assert!(h.breaker_open());
}

#[tokio::test]
async fn an_unreachable_or_hung_market_is_unavailable() {
    let key = key();
    // Nothing listens on port 1.
    let source = MarketSource::new(MarketConfig::for_tests(
        "http://127.0.0.1:1",
        AUDIENCE,
        &key,
    ))
    .unwrap()
    .with_lookup_token(LookupToken::parse(Some(&token_text())).unwrap().unwrap());
    assert_eq!(
        source.subscription(&Uuid::new_v4(), false).await,
        Subscription::Unavailable
    );

    let h = Harness::new().await;
    let account = h.with(Answer::Slow);
    let started = std::time::Instant::now();
    assert_eq!(
        h.source.subscription(&account, false).await,
        Subscription::Unavailable
    );
    assert!(started.elapsed() < Duration::from_secs(MARKET_FETCH_DEADLINE_SECONDS + 2));
}

#[tokio::test]
async fn without_a_token_nothing_is_asked() {
    let h = Harness::new().await;
    let account = h.subscriber();
    let mut plain = MarketSource::new(h.source.config.clone()).unwrap();
    assert_eq!(plain.subscription(&account, true).await, Subscription::None);
    assert_eq!(h.hits(), 0);
    assert!(h.market.seen.lock().unwrap().is_empty());
    plain.subscriptions = None;
}

#[tokio::test]
async fn answers_are_cached_and_a_failure_only_briefly() {
    let h = Harness::new().await;
    let active = h.subscriber();
    let none = Uuid::new_v4();
    for _ in 0..3 {
        assert_eq!(
            h.source.subscription(&active, false).await,
            Subscription::Active
        );
        assert_eq!(
            h.source.subscription(&none, false).await,
            Subscription::None
        );
    }
    assert_eq!(h.hits(), 2, "one lookup per account");

    let now = Utc::now().timestamp();
    let ttl = |account: &Uuid| h.lookup().cache.lock().unwrap()[account].expires_at - now;
    for account in [&active, &none] {
        assert!((MARKET_CACHE_TTL_SECONDS - 2..=MARKET_CACHE_TTL_SECONDS).contains(&ttl(account)));
    }
    let failing = h.with(Answer::Status(503));
    assert_eq!(
        h.source.subscription(&failing, false).await,
        Subscription::Unavailable
    );
    assert!(
        (MARKET_FAILURE_CACHE_TTL_SECONDS - 2..=MARKET_FAILURE_CACHE_TTL_SECONDS)
            .contains(&ttl(&failing))
    );

    // An expired "active" never grants: it is asked again.
    h.close_breaker();
    h.lookup()
        .cache
        .lock()
        .unwrap()
        .get_mut(&active)
        .unwrap()
        .expires_at = now - 1;
    h.market.answers.lock().unwrap().remove(&active.to_string());
    assert_eq!(
        h.source.subscription(&active, false).await,
        Subscription::None
    );
}

#[tokio::test]
async fn a_failure_never_replaces_an_answer_learned_meanwhile() {
    let h = Harness::new().await;
    let account = h.subscriber();
    assert_eq!(
        h.source.subscription(&account, false).await,
        Subscription::Active
    );
    let now = Utc::now().timestamp();
    h.lookup().record(&account, Subscription::Unavailable, now);
    assert_eq!(h.lookup().cached(&account, now), Some(Subscription::Active));
    // An answer does replace a failure.
    let other = Uuid::new_v4();
    h.lookup().record(&other, Subscription::Unavailable, now);
    h.lookup().record(&other, Subscription::None, now);
    assert_eq!(h.lookup().cached(&other, now), Some(Subscription::None));
}

#[tokio::test]
async fn one_failure_stops_lookups_for_every_account() {
    let h = Harness::new().await;
    let held = h.subscriber();
    assert_eq!(
        h.source.subscription(&held, false).await,
        Subscription::Active
    );
    let failing = h.with(Answer::Status(503));
    assert_eq!(
        h.source.subscription(&failing, false).await,
        Subscription::Unavailable
    );
    assert!(h.breaker_open());
    let asked = h.hits();

    // Another account, which the market would answer for, is not asked, and
    // is not taken for "none".
    let second = h.subscriber();
    assert_eq!(
        h.source.subscription(&second, false).await,
        Subscription::Unavailable
    );
    assert_eq!(
        h.source.subscription(&second, true).await,
        Subscription::Unavailable
    );
    assert_eq!(h.hits(), asked);
    assert_eq!(
        h.lookup().cached(&second, Utc::now().timestamp()),
        None,
        "an open breaker is unknown, never cached"
    );
    // What was learned before still grants.
    assert_eq!(
        h.source.subscription(&held, false).await,
        Subscription::Active
    );

    // Once the market answers again the second account is asked.
    h.close_breaker();
    assert_eq!(
        h.source.subscription(&second, false).await,
        Subscription::Active
    );
    assert_eq!(h.hits(), asked + 1);
}

#[test]
fn when_the_breaker_window_ends_one_caller_probes() {
    let lookup = SubscriptionLookup::new(LookupToken::parse(Some(&token_text())).unwrap().unwrap());
    let now = 1_800_000_000;
    assert!(lookup.admit(now), "closed: everyone is admitted");
    assert!(lookup.admit(now));

    lookup.settle(Subscription::Unavailable, now);
    assert!(!lookup.admit(now));
    assert!(!lookup.admit(now + MARKET_FAILURE_CACHE_TTL_SECONDS - 1));

    // The window is up: the first caller probes, the rest still wait.
    let later = now + MARKET_FAILURE_CACHE_TTL_SECONDS;
    assert!(lookup.admit(later));
    assert!(!lookup.admit(later));
    assert!(!lookup.admit(later + MARKET_FETCH_DEADLINE_SECONDS as i64));

    // A probe that fails opens it for another window.
    lookup.settle(Subscription::Unavailable, later + 3);
    assert!(!lookup.admit(later + 3 + MARKET_FAILURE_CACHE_TTL_SECONDS - 1));
    // One that answers closes it, whatever the answer.
    for answer in [Subscription::None, Subscription::Active] {
        lookup.settle(Subscription::Unavailable, now);
        lookup.settle(answer, now + 1);
        assert!(lookup.admit(now + 1));
        assert!(lookup.admit(now + 1));
    }
    // A probe that never reports back does not shut the breaker for good.
    lookup.settle(Subscription::Unavailable, now);
    assert!(lookup.admit(later));
    assert!(lookup.admit(later + MARKET_FETCH_DEADLINE_SECONDS as i64 + 1));
}

#[tokio::test]
async fn a_renewal_rechecks_a_cached_none_within_its_budget() {
    let h = Harness::new().await;
    let account = Uuid::new_v4();
    assert_eq!(
        h.source.subscription(&account, false).await,
        Subscription::None
    );
    // The payment lands.
    h.answer(&account, Answer::Active(h.claim(&account, json!({}))));
    assert_eq!(
        h.source.subscription(&account, false).await,
        Subscription::None,
        "an ordinary mint is served the cached answer"
    );
    assert_eq!(h.hits(), 1);
    assert_eq!(
        h.source.subscription(&account, true).await,
        Subscription::Active
    );
    assert_eq!(h.hits(), 2);
    // A cached "active" is never rechecked.
    assert_eq!(
        h.source.subscription(&account, true).await,
        Subscription::Active
    );
    assert_eq!(h.hits(), 2);

    // An account that stays "none": the budget, then the cache.
    let waiting = Uuid::new_v4();
    assert_eq!(
        h.source.subscription(&waiting, false).await,
        Subscription::None
    );
    let before = h.hits();
    for _ in 0..MARKET_SUBSCRIPTION_RECHECKS_PER_MINUTE + 4 {
        assert_eq!(
            h.source.subscription(&waiting, true).await,
            Subscription::None
        );
    }
    assert_eq!(
        h.hits() - before,
        MARKET_SUBSCRIPTION_RECHECKS_PER_MINUTE as usize
    );
    // The budget is per account.
    let another = Uuid::new_v4();
    assert_eq!(
        h.source.subscription(&another, false).await,
        Subscription::None
    );
    let before = h.hits();
    assert_eq!(
        h.source.subscription(&another, true).await,
        Subscription::None
    );
    assert_eq!(h.hits() - before, 1);
}

#[tokio::test]
async fn a_recheck_never_passes_a_cached_failure_or_an_open_breaker() {
    let h = Harness::new().await;
    let waiting = Uuid::new_v4();
    assert_eq!(
        h.source.subscription(&waiting, false).await,
        Subscription::None
    );
    let failing = h.with(Answer::Status(503));
    assert_eq!(
        h.source.subscription(&failing, true).await,
        Subscription::Unavailable
    );
    let asked = h.hits();
    // The failing account's own cached failure.
    h.close_breaker();
    assert_eq!(
        h.source.subscription(&failing, true).await,
        Subscription::Unavailable
    );
    assert_eq!(h.hits(), asked);
    // Another account's recheck while the breaker is open.
    h.lookup()
        .settle(Subscription::Unavailable, Utc::now().timestamp());
    assert_eq!(
        h.source.subscription(&waiting, true).await,
        Subscription::Unavailable
    );
    assert_eq!(h.hits(), asked);
}

// --------- At a mint (DynamoDB Local) ---------

struct MintFixture {
    h: Arc<Harness>,
    state: AppState,
    store: Arc<crate::db::DynamoDBStore>,
}

impl MintFixture {
    async fn new() -> Option<Self> {
        let store = Arc::new(crate::db::tests::local_store()?);
        let mut state = crate::test_helpers::build_test_app_state_with_store(store.clone());
        let h = Harness::new().await;
        // The state owns its own source, pointed at the same market.
        let source = MarketSource::new(h.source.config.clone())
            .unwrap()
            .with_lookup_token(LookupToken::parse(Some(&h.token)).unwrap().unwrap());
        state.market = Arc::new(Some(source));
        Some(Self {
            h: Arc::new(h),
            state,
            store,
        })
    }

    async fn user(&self) -> Uuid {
        self.store
            .create_user(
                &format!("sub-{}", &Uuid::new_v4().simple().to_string()[..12]),
                "did:key:z6MkSubscription",
            )
            .await
            .unwrap()
            .user_id
    }

    fn subscribe(&self, account: &Uuid) {
        self.h
            .answer(account, Answer::Active(self.h.claim(account, json!({}))));
    }

    async fn derived(&self, account: Uuid) -> Vec<String> {
        crate::publishing::derived_entitlements(&self.state, Some(account), None).await
    }

    async fn suspend(&self, account: &Uuid) {
        self.store
            .set_publishing_suspension(
                account,
                &crate::db::PublishingSuspension {
                    reason: "test".into(),
                    report_id: None,
                    suspended_by: "client:moderation".into(),
                    suspended_at: Utc::now().timestamp(),
                },
            )
            .await
            .unwrap();
    }
}

#[tokio::test]
async fn a_paid_term_grants_online_play_and_nothing_else() {
    let Some(f) = MintFixture::new().await else {
        return;
    };
    let account = f.user().await;
    let other = f.user().await;
    f.subscribe(&account);
    assert_eq!(
        f.derived(account).await,
        vec![ENTITLEMENT_ONLINE_PLAY.to_string()]
    );
    assert!(f.derived(other).await.is_empty());

    // Through the one claims builder every human token uses: derived, never
    // stored, so the registration token drops it.
    let patreon = crate::patreon::PatreonState::new(
        None,
        None,
        fred::clients::RedisClient::new(fred::types::RedisConfig::default(), None, None, None),
    );
    let user = crate::oidc::AuthenticatedUser::webauthn(account, vec![]);
    let claims = crate::oidc::arkavo_user_claims(&f.state, &patreon, &user).await;
    assert!(
        claims
            .derived_entitlements
            .contains(&ENTITLEMENT_ONLINE_PLAY.to_string())
    );
    assert!(
        !claims
            .derived_entitlements
            .contains(&ENTITLEMENT_CREATOR_PUBLISH.to_string())
    );
    assert!(
        !claims
            .entitlements
            .contains(&ENTITLEMENT_ONLINE_PLAY.to_string())
    );
}

#[tokio::test]
async fn a_publishing_suspension_keeps_the_term() {
    let Some(f) = MintFixture::new().await else {
        return;
    };
    let account = f.user().await;
    f.subscribe(&account);
    f.suspend(&account).await;
    assert_eq!(
        f.derived(account).await,
        vec![ENTITLEMENT_ONLINE_PLAY.to_string()]
    );
}

/// An outage withholds the pass and nothing else: the mint goes on, and
/// `GET /entities` (which answers 5xx for an unknown publishing answer) is
/// not failed by it.
#[tokio::test]
async fn a_market_outage_withholds_only_the_pass() {
    let Some(f) = MintFixture::new().await else {
        return;
    };
    let account = f.user().await;
    f.h.answer(&account, Answer::Status(503));
    assert!(f.derived(account).await.is_empty());
    let entities = crate::publishing::try_derived_entitlements(&f.state, Some(account), None).await;
    assert_eq!(entities.unwrap(), Vec::<String>::new());

    // A second account, while the breaker is open: not asked, still a mint.
    let second = f.user().await;
    f.subscribe(&second);
    let asked = f.h.hits();
    assert!(f.derived(second).await.is_empty());
    assert_eq!(f.h.hits(), asked);
    assert!(
        crate::publishing::try_derived_entitlements(&f.state, Some(second), None)
            .await
            .is_ok()
    );
}

#[tokio::test]
async fn a_renewal_sees_a_term_paid_since_the_last_mint() {
    let Some(f) = MintFixture::new().await else {
        return;
    };
    let account = f.user().await;
    let pass = |sources| {
        let state = f.state.clone();
        async move {
            crate::publishing::derive(&state, Some(account), None, sources)
                .await
                .unwrap()
                .entitlements
        }
    };
    let load = |recheck| crate::publishing::load_sources(&f.state, Some(account), recheck);
    assert!(pass(load(false).await.unwrap()).await.is_empty());
    f.subscribe(&account);
    // An ordinary mint within the cache window still says no.
    assert!(pass(load(false).await.unwrap()).await.is_empty());
    assert_eq!(
        pass(load(true).await.unwrap()).await,
        vec![ENTITLEMENT_ONLINE_PLAY.to_string()]
    );
}

#[tokio::test]
async fn an_app_store_pass_is_not_asked_about_and_grants_once() {
    use crate::app_store::{AppStoreApp, AppStoreConfig, Environment, Grant};
    use crate::db::{AppStoreRecord, GraceUpdate};
    const PASS: &str = "com.example.game.pass.monthly";

    let Some(mut f) = MintFixture::new().await else {
        return;
    };
    let mut cfg = AppStoreConfig::for_tests(Vec::new());
    cfg.apps.push(AppStoreApp {
        bundle_id: "com.example.game".into(),
        app_apple_id: 4_242,
        products: HashMap::from([(PASS.to_string(), Grant::OnlinePlay)]),
        environments: [Environment::Production].into(),
    });
    f.state.app_store = Arc::new(Some(cfg));
    let account = f.user().await;
    f.subscribe(&account);
    let otid = Uuid::new_v4().as_u128().to_string();
    let now = Utc::now().timestamp();
    f.store
        .put_app_store_state(
            &account,
            &AppStoreRecord {
                original_transaction_id: otid.clone(),
                transaction_id: Some(otid),
                product_id: PASS.into(),
                environment: Environment::Production,
                expires_at: now + 3600,
                grace_expires_at: None,
                revoked_at: None,
                last_signed_at: now,
            },
            GraceUpdate::Keep,
        )
        .await
        .unwrap();
    assert_eq!(
        f.derived(account).await,
        vec![ENTITLEMENT_ONLINE_PLAY.to_string()]
    );
    assert_eq!(f.h.hits(), 0, "the App Store already grants: no lookup");
}
